/* Three-role workflow prototype: workers own domain records; coordinator aggregates and routes. */
document.body.classList.add('coordinator-mode');state.coordinatorMessages=state.coordinatorMessages||[];state.workerDirectives=state.workerDirectives||{work:'Ưu tiên theo hạn và tiến độ content',life:'Giữ nhịp sinh hoạt, học tập và tiết kiệm'};state.workerJournal=state.workerJournal||[];let cReports={};const workerName=k=>k==='work'?'Agent Công việc':'Agent Cuộc sống';const workerIcon=k=>k==='work'?'briefcase':'heart';function workerTasks(k){return state.tasks.filter(t=>(k==='work'?workcats:categories).some(c=>c.id===t.category))}function collectWorkerReport(k){const tasks=workerTasks(k),range=periodRange(),open=tasks.filter(t=>!t.done),inPeriod=tasks.filter(t=>t.date&&t.date>=range.start&&t.date<=range.end),late=open.filter(t=>t.date&&t.date<today),undated=open.filter(t=>!t.date),priority=open.slice().sort((a,b)=>{if(k==='work'&&/content/i.test(state.workerDirectives.work)&&a.category!==b.category){if(a.category==='content')return -1;if(b.category==='content')return 1}return (a.date||'9999').localeCompare(b.date||'9999')});const top=priority[0];return {kind:k,name:workerName(k),open,inPeriod,late,undated,priority,directive:state.workerDirectives[k],summary:open.length?`${open.length} việc đang theo dõi. ${top?'Ưu tiên: '+top.title+'.':''}`:'Chưa có việc mở trong mảng này.',detail:late.length?`${late.length} việc qua ngày dự định; đã đưa vào danh sách cần rà lại.`:undated.length?`${undated.length} việc chưa có ngày; giữ trong danh sách để lên lịch sau.`:'Chưa phát hiện việc quá hạn trong dữ liệu hiện tại.'}}function runWorkers(){cReports={work:collectWorkerReport('work'),life:collectWorkerReport('life')};return cReports}function coordinatorDecision(){const open=state.tasks.filter(t=>!t.done&&t.date===today);return open.length>=5&&!state.coordinatorBalance?{title:'Hai mảng đang cùng có nhiều việc hôm nay.',detail:`Hai agent báo tổng cộng ${open.length} việc có ngày dự định hôm nay. Bạn muốn nghiêng về công việc hay giữ cân bằng? Mình sẽ chuyển định hướng xuống cả hai con. Chưa có thời lượng để tự dời lịch.`,options:[['work','Ưu tiên công việc'],['balanced','Giữ cân bằng']]}:null}function crewCard(k){const r=cReports[k];return `<button class="crew-card" data-workerreport="${k}"><div class="crew-card-head"><span class="crew-icon" style="--bg:${k==='work'?'#eef0f8':'#eef4ec'};--fg:${k==='work'?'#a2a7c0':'#a1b497'}">${icon(workerIcon(k))}</span><div><h3>${r.name}</h3><small><i></i>Đã rà dữ liệu local · Mô phỏng</small></div></div><p>${esc(r.directive)}</p><div class="crew-bottom"><span>${r.open.length} việc đang theo dõi · ${r.inPeriod.length} có lịch trong kỳ</span>${icon('arrow')}</div></button>`}function coordinatorDigest(){runWorkers();const decision=coordinatorDecision(),reports=Object.values(cReports),n=reports.reduce((s,r)=>s+r.inPeriod.filter(t=>!t.done).length,0);return `<section class="coord-intro"><div class="coord-eyebrow">${icon('grid')}MỘT ĐẦU MỐI. HAI AGENT LO VIỆC.</div><h2>Hai agent theo dõi bên dưới.<br><em>Bạn nhận điều đáng biết ở đây.</em></h2><p>Agent tổng nhận báo cáo từ Công việc và Cuộc sống, gom thông báo rồi trao đổi với bạn khi cần đổi hướng. Việc chi tiết do từng agent phụ trách.</p><div class="crew-row">${crewCard('work')}${crewCard('life')}</div><div class="crew-routing"><i></i>${icon('up')}Báo cáo lên Agent tổng<i></i></div></section><div class="coord-controls">${tabsHTML()}<button class="coord-run" data-coordrun="yes">${icon('spark')}Thử một vòng báo cáo</button></div><section class="coord-bulletin"><div class="coord-bulletin-top"><strong>${icon('bell')}Tổng gửi bạn · ${periodName()}</strong><time>${periodLabel()}</time></div><div class="coord-bulletin-body"><p>Hai agent đã tổng hợp dữ liệu. Có ${n} việc còn mở được đặt lịch trong ${overviewPeriod==='day'?'ngày':overviewPeriod==='week'?'tuần':'tháng'} này. ${state.coordinatorBalance?'Định hướng đang áp dụng: '+(state.coordinatorBalance==='work'?'ưu tiên công việc.':'giữ cân bằng hai mảng.'):'Chi tiết được gom trong map bên cạnh.'}</p>${reports.map(r=>`<div class="coord-summary-line">${icon(workerIcon(r.kind))}<div><strong>${r.name} báo lên</strong><p>${esc(r.summary)}<br>${esc(r.detail)}</p></div><button data-workerreport="${r.kind}">Báo cáo ↗</button></div>`).join('')}${decision?`<div class="coord-decision"><div class="decision-eyebrow">${icon('spark')}CẦN BẠN QUYẾT ĐỊNH HƯỚNG</div><p><strong>${decision.title}</strong><br>${decision.detail}</p><div class="decision-options">${decision.options.map(([id,label])=>`<button data-balance="${id}">${label}</button>`).join('')}</div></div>`:`<div class="coord-policy">${icon('check')}Chưa có quyết định chung nào cần bạn xử lý. Hai agent tiếp tục giữ danh sách theo dõi của mình.</div>`}<div class="coord-health">Đây là mô phỏng luồng 3 agent bằng dữ liệu local. Chưa có model hoặc agent chạy nền thật; chưa đọc app CV, Zalo hay lịch cá nhân.</div></div></section>`}function receiptHTML(m){if(!m.receipts)return '';return `<div class="coord-receipt">${m.receipts.map(r=>`<div class="coord-receipt-step">${icon(r.kind==='total'?'bell':workerIcon(r.kind))}<div><strong>${r.kind==='total'?'Agent tổng':workerName(r.kind)}</strong><span>${esc(r.text)}</span></div></div>`).join('')}<div class="coord-receipt-bottom">${icon('check')}Kết quả đã phản ánh trên map${m.undo&&state.coordinatorLastUndo===m.id?`<button data-cundo="${m.id}">Hoàn tác thay đổi</button>`:''}</div></div>`}aFeed=function(scroll=true){$('#athreadcontent').innerHTML=coordinatorDigest()+(state.coordinatorMessages.length?'<div class="coord-feedlabel">THÔNG BÁO & ĐIỀU CHỈNH</div>':'')+state.coordinatorMessages.map(m=>m.role==='user'?`<div class="user-message"><div class="user-bubble">${esc(m.text)}</div><time>${esc(m.time)}</time></div>`:`<div class="agent-message"><span class="message-face">✳</span><div class="message-body"><div class="message-meta">Agent tổng <time>${esc(m.time)}</time></div><div class="message-text ${m.proactive?'coord-notification':''}">${esc(m.text)}</div>${receiptHTML(m)}${m.reference?`<div class="map-reference">${icon('grid')}${esc(m.reference)}</div>`:''}</div></div>`).join('');$('#acontext').innerHTML=icon('lock')+'Tổng nhận thông báo · CV & CS xử lý phần việc của mình';if(scroll)setTimeout(()=>{$('#athread').scrollTop=$('#athread').scrollHeight},30)};const workerMapRender=aMap;aMap=function(){runWorkers();workerMapRender();const marker=document.createElement('div');marker.className='coord-map-source';marker.innerHTML=icon('briefcase')+' Agent CV '+icon('plus')+' Agent CS → Map tổng';$('#amap').insertBefore(marker,$('#amap').children[1]||null)};function cPush(text,extra={}){const m={id:aId(),role:'assistant',time:aTime(),text,...extra};state.coordinatorMessages.push(m);aSave();aFeed();aMap();return m}function cFinish(text,receipts,undo=[]){const m={id:aId(),role:'assistant',time:aTime(),text,receipts,undo:undo.length?undo:null};if(undo.length)state.coordinatorLastUndo=m.id;state.coordinatorMessages.push(m);aSave();aFeed();aMap()}function executeWorker(k,commands){const receipts=[],undo=[];for(const cmd of commands){if(cmd.type==='directive'){const before=state.workerDirectives[k];state.workerDirectives[k]=cmd.text;undo.push({type:'directive',kind:k,before});receipts.push('Đã cập nhật định hướng: '+cmd.text+'. Thứ tự theo dõi được rà lại.');continue}if(cmd.type==='add'){const duplicate=workerTasks(k).find(t=>!t.done&&norm(t.title)===norm(cmd.title));if(duplicate){receipts.push('Việc “'+duplicate.title+'” đã có trong danh sách; đã giữ một bản.');continue}const t={id:Date.now()+Math.random(),title:cmd.title,category:cmd.category,date:cmd.date||'',time:'',done:false};state.tasks.push(t);undo.push({type:'remove',id:t.id});receipts.push('Đã ghi nhận “'+t.title+'”'+(t.date?' · '+dateLabel(t.date):' · chưa có hạn cụ thể')+'.');continue}const t=workerTasks(k).find(t=>t.id===cmd.taskId);if(!t)continue;undo.push({type:'restore',task:{...t}});if(cmd.type==='complete'){t.done=true;receipts.push('Đã đánh dấu hoàn thành “'+t.title+'”.')}if(cmd.type==='move'){t.date=cmd.date;receipts.push('Đã dời “'+t.title+'” sang '+dateLabel(t.date)+'.')}}state.workerJournal.push({id:aId(),kind:k,time:aTime(),text:receipts.join(' ')});return {receipt:{kind:k,text:receipts.join(' ')||'Đã rà lại danh sách theo dõi.'},undo}}function cDispatch(text,jobs){const receipts=[{kind:'total',text:'Đã chuyển yêu cầu tới '+Object.keys(jobs).map(workerName).join(' và ')+'.'}],undo=[];for(const [k,commands]of Object.entries(jobs)){const result=executeWorker(k,commands);receipts.push(result.receipt);undo.push(...result.undo)}cFinish(text,receipts,undo)}function cBalance(kind){const previous=state.coordinatorBalance;state.coordinatorBalance=kind;const jobs=kind==='work'?{work:[{type:'directive',text:'Ưu tiên content và việc có hạn gần'}],life:[{type:'directive',text:'Giữ việc thiết yếu; gom việc cá nhân chưa gấp để rà sau'}]}:{work:[{type:'directive',text:'Bám hạn công việc; rà khối lượng trước khi nhận thêm'}],life:[{type:'directive',text:'Giữ nhịp sinh hoạt, học tập và thời gian nghỉ'}]};cDispatch('Đã chuyển định hướng xuống cả hai agent. Hai con sẽ theo dõi theo ưu tiên mới; việc nào cần dời lịch cụ thể sẽ được tổng hợp để trao đổi.',jobs);const last=state.coordinatorMessages.at(-1);if(last?.undo)last.undo.push({type:'balance',before:previous});aSave()}function cUndo(id){const m=state.coordinatorMessages.find(m=>m.id===id);if(!m||!m.undo||state.coordinatorLastUndo!==id)return;m.undo.slice().reverse().forEach(u=>{if(u.type==='balance')state.coordinatorBalance=u.before;if(u.type==='directive')state.workerDirectives[u.kind]=u.before;if(u.type==='remove')state.tasks=state.tasks.filter(t=>t.id!==u.id);if(u.type==='restore'){const idx=state.tasks.findIndex(t=>t.id===u.task.id);if(idx<0)state.tasks.push(u.task);else state.tasks[idx]=u.task}});state.coordinatorLastUndo=null;aSave();aFeed(false);aMap();toast('Đã hoàn tác lần điều chỉnh gần nhất.')}function cWorkerReport(k){runWorkers();const r=cReports[k];showModal(r.name+' → Báo cáo cho Tổng',`<div class="worker-report"><p><strong>Phạm vi:</strong> ${k==='work'?'Content, dự án, bot Zalo và thông tin công việc.':'Học tập, mục tiêu, sức khỏe, du lịch và sinh hoạt cá nhân.'}</p><p><strong>Định hướng:</strong> ${esc(r.directive)}</p><h3>Đã tổng hợp</h3><p>${r.open.length} việc còn mở · ${r.late.length} quá ngày dự định · ${r.undated.length} chưa có lịch.</p><h3>Danh sách agent đang giữ</h3><div class="map-group">${reportRows(workerTasks(k),true)}</div><h3>Kết quả xử lý gần nhất</h3>${state.workerJournal.filter(j=>j.kind===k).slice(-4).reverse().map(j=>`<p>${esc(j.time)} · ${esc(j.text)}</p>`).join('')||'<p>Đã rà dữ liệu mẫu và gửi báo cáo trạng thái lên Tổng.</p>'}<p class="modal-info">Mô phỏng phân vai tại trình duyệt. Agent này chưa kết nối API, app bên ngoài hoặc chạy khi đóng web.</p></div>`)}function cRun(){runWorkers();cPush('Mình vừa nhận báo cáo từ cả hai con. Đây là một lượt mô phỏng cách chúng tự rà rồi gửi thông tin lên — bạn chỉ nhận phần tổng hợp.',{proactive:true,receipts:[{kind:'work',text:cReports.work.summary+' '+cReports.work.detail},{kind:'life',text:cReports.life.summary+' '+cReports.life.detail},{kind:'total',text:'Đã gom báo cáo, rà các việc cùng ngày và cập nhật tổng quan '+periodName().toLowerCase()+'.'}],reference:'Không thêm việc hoặc thay đổi lịch trong lượt rà này.'})}function cHandle(q){const s=norm(q);if(/^(chao|hi|hello|alo)[!. ]*$/.test(s)){cPush('Mình đây. Hai agent phụ trách từng mảng; bạn cứ đưa định hướng hoặc nói điều đang thay đổi, mình chuyển xuống đúng con rồi báo kết quả.');return}if(/hoan tac/.test(s)){if(state.coordinatorLastUndo)cUndo(state.coordinatorLastUndo);else cPush('Chưa có điều chỉnh nào đang có thể hoàn tác.');return}if(/tong quan|ban tin|hom nay.*(gi|lo)|tuan nay co gi|thang nay co gi/.test(s)){const p=/thang/.test(s)?'month':/tuan/.test(s)?'week':'day';setPeriod(p);runWorkers();cPush(periodName(p)+' · '+periodLabel(p)+'\n\nCông việc: '+cReports.work.summary+'\nCuộc sống: '+cReports.life.summary+'\n\n'+(coordinatorDecision()?'Có một quyết định hướng chung đang chờ ở bản tin.':'Chưa có quyết định chung nào cần bạn xử lý.'),{reference:'Bản tổng hợp lấy từ hai agent phụ trách; map đã mở đúng kỳ.'});return}if(/uu tien.*(cong viec|content)|giam.*(ca nhan|cuoc song)|tuan nay.*(content).*giam/.test(s)){cBalance('work');return}if(/can bang|giu nhip/.test(s)){cBalance('balanced');return}if(/bao cao.*(cv|cong viec)|agent.*cong viec/.test(s)&&!/can|phai|them/.test(s)){cWorkerReport('work');return}if(/bao cao.*(cs|cuoc song)|agent.*cuoc song/.test(s)&&!/can|phai|them/.test(s)){cWorkerReport('life');return}if(/xong|hoan thanh|doi.*(mai|ngay|tuan)|hoan.*(mai|ngay|tuan)/.test(s)){const matches=matchTask(q);if(matches.length!==1){cPush(matches.length?'Agent phụ trách thấy nhiều việc khớp. Bạn nhắc rõ tên việc để con đó cập nhật đúng nhé.':'Chưa tìm được việc khớp trong dữ liệu của hai agent. Bạn nhắc tên việc cụ thể giúp mình.');return}const t=matches[0],k=workcats.some(c=>c.id===t.category)?'work':'life';if(/xong|hoan thanh/.test(s))cDispatch('Đã nhận kết quả. '+workerName(k)+' đã cập nhật phần việc này.',{[k]:[{type:'complete',taskId:t.id}]});else{const date=scheduleFor(q);if(!date){cPush('Bạn muốn dời sang ngày nào? Bản thử hiểu “ngày mai” và “tuần sau”.');return}cDispatch('Đã chuyển thay đổi lịch cho '+workerName(k)+'.',{[k]:[{type:'move',taskId:t.id,date}]})}return}if(/met|qua tai|duoi|nghi ngoi/.test(s)){cDispatch('Mình đã chuyển yêu cầu giảm tải xuống hai agent. Các con rà lại theo hướng giữ việc thiết yếu và dành khoảng nghỉ; chưa tự thay đổi hạn đã hẹn.',{work:[{type:'directive',text:'Rà việc có hạn gần, gom việc chưa gấp để giảm tải'}],life:[{type:'directive',text:'Ưu tiên nghỉ ngơi và sinh hoạt thiết yếu'}]});return}if(/nguon|ket noi|lay thong tin/.test(s)){sourceInfo();return}if(/^(cam on|ok|oke|duoc|uh|u)[!. ]*$/.test(s)){cPush('Đã rõ. Các định hướng và phần việc hiện tại được giữ trong từng agent. Có điểm cần bạn quyết, Tổng sẽ gom lại báo.');return}const date=scheduleFor(q),commands=[];if(/content|bai viet/.test(s)){const count=s.match(/(\d+)\s*bai/);commands.push({type:'add',title:count?'Viết '+count[1]+' bài content'+(/tuan nay/.test(s)?' tuần này':''):q,category:'content',date})}if(/tap|gym|yoga|chay bo/.test(s)&&!/tap trung/.test(s)){const count=s.match(/(\d+)\s*buoi/);commands.push({type:'add',title:count?'Tập luyện '+count[1]+' buổi trong tuần':'Dành thời gian tập luyện',category:'health',date})}if(/tiet kiem/.test(s)){const amt=s.match(/(\d+(?:[.,]\d+)?)\s*(trieu|tr|k|nghin)/);commands.push({type:'add',title:'Dành '+(amt?amt[1]+' '+(amt[2]==='tr'?'triệu':amt[2]):'một khoản')+' tiết kiệm',category:'money',date})}if(!commands.length){if(/\?|co nen|nghi sao/.test(s)){cPush('Mình hiểu đây là trao đổi định hướng, chưa phải giao việc. Trong demo này, mình xử lý được giao việc, đổi ưu tiên, báo xong và dời lịch; phần tư vấn mở cần nối model thật.');return}const category=categoryFor(q);commands.push({type:'add',title:q.replace(/^(tao|tôi|mình)\s+(cần|muốn|phải)\s+/i,'').trim(),category,date})}const jobs={};commands.forEach(c=>{const k=workcats.some(x=>x.id===c.category)?'work':'life';(jobs[k]??=[]).push(c)});cDispatch('Đã giao xuống đúng agent. Các con đã ghi nhận phần việc của mình và trả kết quả về đây. Bạn không cần mở từng mảng để thêm thủ công.',jobs)}aSend=function(q){q=q.trim().slice(0,3000);if(!q)return;state.coordinatorMessages.push({id:aId(),role:'user',text:q,time:aTime()});$('#acompose').value='';cHandle(q);aSave();aFeed();aMap();$('#acompose').focus()};aHistory=function(){const messages=state.coordinatorMessages.filter(m=>m.role==='user');showModal('Điều bạn đã trao đổi với Tổng',messages.length?`<div class="calendar-list">${messages.slice().reverse().map(m=>`<div class="calendar-entry"><div><strong>${esc(m.text)}</strong><p>${esc(m.time)}</p></div></div>`).join('')}</div>`:'<p class="modal-info">Chưa có điều chỉnh nào. Bản tin hiện tại do hai agent tổng hợp từ dữ liệu mẫu.</p>')};checkBriefSchedule=function(){};$('#mainnav').innerHTML=`<button class="nav-item active" data-coordnav="top">${icon('bell')}Thông báo từ Tổng</button><button class="nav-item" data-openreport="yes">${icon('grid')}Map ngày / tuần / tháng</button><button class="nav-item" id="chistory">${icon('clock')}Điều chỉnh đã trao đổi</button>`;$('#chistory').onclick=aHistory;$('.areas-label').innerHTML='AGENT TRỰC THUỘC';$('#areanav').innerHTML=`<button class="nav-item" data-workerreport="work">${icon('briefcase')}Agent Công việc</button><button class="nav-item" data-workerreport="life">${icon('heart')}Agent Cuộc sống</button><div class="agent-nav-note">CV và CS giữ việc chi tiết.<br>Tổng gom báo cáo, chuyển chỉ đạo<br>và trao đổi quyết định với bạn.</div><div class="side-label" style="margin-top:22px">DỮ LIỆU & CÁCH CHẠY</div><button class="nav-item" data-sources="yes">${icon('note')}Nguồn thông tin</button>`;document.querySelector('.conversation-id h1').textContent='Agent tổng · Đầu mối của bạn';document.querySelector('.conversation-id p').innerHTML='<span class="agent-status"></span>Nhận báo cáo từ CV & CS · Chuyển điều chỉnh xuống';$('#acompose').placeholder='Điều chỉnh cho các agent… Ví dụ: tuần này ưu tiên content, giảm việc cá nhân';document.querySelector('.composer-tools').innerHTML=icon('spark')+'Bạn ↔ Tổng<span>·</span>Tổng ↔ CV & CS';document.querySelector('.composer-note').innerHTML='<span>Việc nhỏ giao đúng agent xử lý. Quyết định chung mới cần trao đổi với bạn.</span><span>Enter để gửi</span>';$('#asimulation').textContent='LUỒNG 3 AGENT · DEMO';$('#ahistory').onclick=aHistory;document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.workerreport)cWorkerReport(b.dataset.workerreport);if(b.dataset.coordrun)cRun();if(b.dataset.balance)cBalance(b.dataset.balance);if(b.dataset.cundo)cUndo(b.dataset.cundo);if(b.dataset.coordnav){$('#athread').scrollTop=0;document.body.classList.remove('sidebar-open')}});aSave();aFeed(false);aMap();
